function normalizeArticle(article) {
  if (!article || typeof article !== 'object') return article;
  const image = article.coverImage || article.image || 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=600';
  const excerpt = article.excerpt || article.summary || '';
  return {
    ...article,
    coverImage: image,
    image,
    excerpt,
    summary: excerpt || article.summary || '',
    readTime: article.readTime || '6 min',
    status: article.status || 'Published',
    date: article.date || new Date().toISOString().split('T')[0],
    author: article.author || 'SmartFiQ Author',
    authorRole: article.authorRole || 'AI Researcher',
    content: article.content || ''
  };
}

function normalizeDb(raw) {
  const seeds = getSeedData();
  const data = raw && typeof raw === 'object' ? raw : {};

  if (!Array.isArray(data.visitors)) data.visitors = seeds.visitors;
  if (!Array.isArray(data.leads)) data.leads = seeds.leads;
  if (!Array.isArray(data.services)) data.services = seeds.services;
  if (!Array.isArray(data.blogs)) data.blogs = seeds.blogs;
  if (!Array.isArray(data.portfolio)) data.portfolio = seeds.portfolio;
  if (!Array.isArray(data.appointments)) data.appointments = seeds.appointments;
  if (!Array.isArray(data.proposals)) data.proposals = seeds.proposals;
  if (!Array.isArray(data.invoices)) data.invoices = seeds.invoices;
  if (!Array.isArray(data.team)) data.team = seeds.team;
  if (!Array.isArray(data.agencyTeam)) data.agencyTeam = seeds.agencyTeam;
  if (!Array.isArray(data.caseStudies)) data.caseStudies = seeds.caseStudies;
  if (!Array.isArray(data.users) || data.users.length === 0) data.users = seeds.users;
  if (!Array.isArray(data.securityLogs)) data.securityLogs = seeds.securityLogs;
  if (!Array.isArray(data.apiKeys)) data.apiKeys = seeds.apiKeys;
  if (!data.cms || typeof data.cms !== 'object') data.cms = seeds.cms;
  if (!data.settings || typeof data.settings !== 'object') data.settings = seeds.settings;
  if (!data.legalCms || typeof data.legalCms !== 'object') data.legalCms = {};

  data.blogs = data.blogs.map(normalizeArticle);
  return data;
}

function readJsonFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) return null;
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (err) {
    console.warn(`DB read warning (${filePath}):`, err.message);
    return null;
  }
}

function initDb() {
  if (!fs.existsSync(DB_FILE)) {
    const seed = readJsonFile(REPO_DB_FILE) || getSeedData();
    try {
      fs.writeFileSync(DB_FILE, JSON.stringify(normalizeDb(seed), null, 2));
    } catch (err) {
      console.warn('DB file write warning:', err.message);
    }
  }
}

async function remoteCommand(command) {
  const config = getRedisConfig();
  if (!config) return null;
  const response = await axios.post(config.url, command, {
    headers: {
      Authorization: `Bearer ${config.token}`,
      'Content-Type': 'application/json'
    },
    timeout: 7000
  });
  if (response.data && response.data.error) {
    throw new Error(response.data.error);
  }
  return response.data ? response.data.result : null;
}

async function loadRemoteDb() {
  const result = await remoteCommand(['GET', REMOTE_DB_KEY]);
  if (!result) return null;
  return typeof result === 'string' ? JSON.parse(result) : result;
}

async function saveRemoteDb(data) {
  await remoteCommand(['SET', REMOTE_DB_KEY, JSON.stringify(data)]);
}

async function ensureReady() {
  if (hydrated) return;
  if (hydrationPromise) return hydrationPromise;

  hydrationPromise = (async () => {
    let data = null;
    if (getRedisConfig()) {
      try {
        data = await loadRemoteDb();
      } catch (err) {
        console.warn('Remote DB load warning, falling back to local cache:', err.message);
      }
    }

    if (!data) {
      initDb();
      data = readJsonFile(DB_FILE) || readJsonFile(REPO_DB_FILE) || getSeedData();
      if (getRedisConfig()) {
        try {
          await saveRemoteDb(normalizeDb(data));
        } catch (err) {
          console.warn('Remote DB initial save warning:', err.message);
        }
      }
    }

    global.smartfiq_in_memory_db = normalizeDb(data);
    hydrated = true;
  })();

  return hydrationPromise;
}

function readDb() {
  if (!global.smartfiq_in_memory_db) {
    initDb();
    global.smartfiq_in_memory_db = normalizeDb(readJsonFile(DB_FILE) || readJsonFile(REPO_DB_FILE) || getSeedData());
  } else {
    global.smartfiq_in_memory_db = normalizeDb(global.smartfiq_in_memory_db);
  }
  return global.smartfiq_in_memory_db;
}

function flushDbToDisk(data) {
  try {
    fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));
    if (!process.env.VERCEL && DB_FILE !== REPO_DB_FILE) {
      fs.writeFileSync(REPO_DB_FILE, JSON.stringify(data, null, 2));
    }
  } catch (err) {
    console.warn('DB file write warning (memory still updated):', err.message);
  }
}

async function writeDb(data) {
  const normalized = normalizeDb(data);
  if (normalized.visitors.length > 2000) {
    normalized.visitors = normalized.visitors.slice(-2000);
  }

  global.smartfiq_in_memory_db = normalized;

  if (global.smartfiq_invalidate_cache) {
    global.smartfiq_invalidate_cache();
  }

  if (writeTimeout) clearTimeout(writeTimeout);
  writeTimeout = setTimeout(() => {
    flushDbToDisk(normalized);
    writeTimeout = null;
  }, 300);

  if (getRedisConfig()) {
    pendingRemoteWrite = pendingRemoteWrite
      .catch(() => {})
      .then(() => saveRemoteDb(normalized))
      .catch(err => {
        console.warn('Remote DB save warning:', err.message);
      });
    await pendingRemoteWrite;
  }

  return true;
}

async function updateCMS(cmsData) {
  const database = readDb();
  database.cms = { ...database.cms, ...cmsData };
  await writeDb(database);
  return database.cms;
}

async function updateSettings(settingsData) {
  const database = readDb();
  database.settings = { ...database.settings, ...settingsData };
  await writeDb(database);
  return database.settings;
}

module.exports = {
  getSeedData,
  normalizeArticle,
  ensureReady,
  readDb,
  writeDb,
  updateCMS,
  updateSettings
};
